{"summary": "Extract list of countries with 2025 data in Value/Volume/Total Reserves", "security_risk": "LOW", "command": "python3 - <<'PY'
import re, math
from openpyxl import load_workbook
wb=load_workbook('/root/data/test-rar.xlsx')

def countries_with_2025(sheet):
    ws=wb[sheet]
    # row for 2025
    r2025=None
    for r in range(1, ws.max_row+1):
        if ws.cell(r,1).value=='2025':
            r2025=r
            break
    assert r2025
    out=[]
    for c in range(3, ws.max_column+1):
        v=ws.cell(r2025,c).value
        if isinstance(v,(int,float)) and not (isinstance(v,float) and math.isnan(v)):
            desc=ws.cell(1,c).value
            if not desc:
                continue
            country=desc.split(':',1)[0].strip()
            out.append((country,c,v,desc))
    return out

for sheet in ['Value','Volume','Total Reserves']:
    lst=countries_with_2025(sheet)
    print('\n',sheet,'count',len(lst))
    for t in lst:
        print(t[0], 'col', t[1], 'val', t[2])
PY"}

